public class NDXSNAllianceItemGroups extends common
{
}

Method.Source:
/// <summary>
/// finds a NDX_SNAllianceItemGroups record for provided PriceGroupId, NDXCompanys and AVATOSId
/// </summary>
/// <param name = "_itemGroup">item group</param>
/// <param name = "_companys">NDXCompanys</param>
/// <param name = "_tosId">AVATOSId</param>
/// <param name = "_selectForUpdate">boolean</param>
/// <returns>NDXSNAllianceClients</returns>
public static NDXSNAllianceItemGroups findPriceGroupTOS(
    ItemGroupId     _itemGroup,
    NDXCompanys     _companys,
    AVATOSId        _tosId,
    boolean         _selectForUpdate = false)
{
    NDXSNAllianceItemGroups alliancePriceGroup;

    if(_selectForUpdate)
    {
        alliancePriceGroup.selectForUpdate(_selectForUpdate);
    }

    select firstonly alliancePriceGroup
        where alliancePriceGroup.ArtGrp   == _itemGroup
            && alliancePriceGroup.Companys == _companys
            && alliancePriceGroup.TOSId    == _tosId;

    return alliancePriceGroup;
}

/// <summary>
/// checks if a records exists in NDX_SNAllianceItemGroups with provided TOSId and PriceGroupId
/// </summary>
/// <param name = "_priceGroupId">PriceGroupId</param>
/// <param name = "_tosId">AVATOSId</param>
/// <param name = "_companys">NDXCompanys</param>
/// <returns>boolean</returns>
public static boolean existsRecordPriceGroupTOS(
    PriceGroupId    _priceGroupId,
    AVATOSId        _tosId,
    NDXCompanys     _companys)
{
    return NDXSNAllianceItemGroups::findPriceGroupTOS(_priceGroupId, _companys, _tosId).RecId;
}

/// <summary>
/// creates new NDX_SNAllianceItemGroups records for not yet existing Party records in provided TOS
/// </summary>
/// <param name = "_tosId">AVATOSId</param>
public static void populateClientsForTOSId(AVATOSId _tosId)
{
    NDXSNAllianceItemGroups    allianceItemGroups;
    NDXSNCompanys           allianceCompanys;
    PriceDiscGroup              priceDiscGroup;
    RecordInsertList            insertList = new RecordInsertList(tableNum(NDXSNAllianceItemGroups));

    ttsbegin;

    while select crosscompany priceDiscGroup
        join allianceCompanys
        order by priceDiscGroup.GroupId
        where priceDiscGroup.Module == ModuleInventCustVend::Invent
        && priceDiscGroup.DataAreaId == allianceCompanys.CompanyId
        && (priceDiscGroup.Type == PriceGroupType::LineDiscGroup
            || priceDiscGroup.Type == PriceGroupType::MultiLineDiscGroup)
    {
        if(NDXSNAllianceItemGroups::existsRecordPriceGroupTOS(priceDiscGroup.GroupId, _tosID, NDXHelperCommon::CompanyId2NDXCompany(priceDiscGroup.company())))
        {
            continue;
        }

        allianceItemGroups.clear();

        allianceItemGroups.TOSId        = _tosId;
        allianceItemGroups.Companys     = NDXHelperCommon::CompanyId2NDXCompany(priceDiscGroup.company());
        allianceItemGroups.ArtGrp = priceDiscGroup.GroupId;
        allianceItemGroups.Determined   = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());

        allianceItemGroups.insert();
    }

    insertList.insertDatabase();

    ttscommit;

}

/// <summary>
/// find
/// </summary>
/// <param name = "_alliance">alliance</param>
/// <param name = "_company">company </param>
/// <param name = "_artGrp">item group</param>
/// <param name = "_update">for update </param>
/// <returns>NDXSNAllianceItemGroups record</returns>
static NDXSNAllianceItemGroups find(CustAccount _alliance, NDXCompanyBE _company, NDXItemGroup _artGrp, boolean _update = false)
{
    NDXSNAllianceItemGroups nDX_SNAllianceItemGroups;

    nDX_SNAllianceItemGroups.selectForUpdate(_update);

    select firstonly nDX_SNAllianceItemGroups
        where nDX_SNAllianceItemGroups.TOSId == _alliance
            && nDX_SNAllianceItemGroups.Companys == _company
            && nDX_SNAllianceItemGroups.ArtGrp == _artGrp;

    return nDX_SNAllianceItemGroups;
}

/// <summary>
/// find or create
/// </summary>
/// <param name = "_alliance">alliance</param>
/// <param name = "_company">company</param>
/// <param name = "_artGrp">item group</param>
/// <returns>NDXSNAllianceItemGroups record</returns>
static NDXSNAllianceItemGroups findOrCreate(CustAccount _alliance, NDXCompanyBE _company, NDXItemGroup _artGrp)
{
    NDXSNAllianceItemGroups nDX_SNAllianceItemGroups;

    nDX_SNAllianceItemGroups = NDXSNAllianceItemGroups::find(_alliance, _company, _artGrp, true);

    if (!nDX_SNAllianceItemGroups)
    {
        nDX_SNAllianceItemGroups.TOSId   = _alliance;
        nDX_SNAllianceItemGroups.Companys = _company;
        nDX_SNAllianceItemGroups.ArtGrp = _artGrp;
        nDX_SNAllianceItemGroups.Determined = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
        nDX_SNAllianceItemGroups.insert();
    }

    return nDX_SNAllianceItemGroups;
}
